class BaseResource {
public:
    virtual ~BaseResource() { /* Base cleanup done last */ }
};

class Intermediate : public BaseResource {
    int* ptr_mid;
public:
    Intermediate() : ptr_mid(new int(1)) {}
    ~Intermediate() override { delete ptr_mid; /* Order 2 */ }
};

class Final : public Intermediate {
    char* ptr_final;
public:
    Final() : ptr_final(new char('a')) {}
    ~Final() override { delete ptr_final; /* Order 1 (First called) */ }
};

// Deletion order (with virtual Base ~): Final -> Intermediate -> Base
// B* obj = new Final(); delete obj;
// Mandatory: Base destructor MUST be virtual.
